// src/Components/VectorMap.jsx
import { useRef, useEffect } from "react";
import maplibregl from "maplibre-gl";
import MapboxDraw from "@mapbox/mapbox-gl-draw";
import "maplibre-gl/dist/maplibre-gl.css";
import "@mapbox/mapbox-gl-draw/dist/mapbox-gl-draw.css";

/**
 * Props:
 * - center: [lng, lat]
 * - zoom: number
 * - apiKey: optional MapTiler key string
 * - onDrawChange: (geojsonFeatureCollection) => void  // fired when drawings change
 */
export default function VectorMap({
  center = [79.109468, 21.096398],
  zoom = 18,
  apiKey,
  onDrawChange,
}) {
  const mapRef = useRef(null);
  const drawRef = useRef(null);
  const mapInstance = useRef(null);

  useEffect(() => {
    const key =
      apiKey ||
      (import.meta?.env?.VITE_MAPTILER_KEY) ||
      process.env.REACT_APP_MAPTILER_KEY ||
      "PASTE_YOUR_KEY_HERE";

    if (!mapRef.current) return;

    const styleUrl = `https://api.maptiler.com/maps/streets-v2/style.json?key=${key}`;

    const map = new maplibregl.Map({
      container: mapRef.current,
      style: styleUrl,
      center,
      zoom,
      maxZoom: 23,
    });

    mapInstance.current = map;

    // Add a simple marker for reference
    new maplibregl.Marker().setLngLat(center).addTo(map);

    // Initialize draw controls
    const draw = new MapboxDraw({
      displayControlsDefault: false,
      controls: {
        polygon: true,
        line_string: true,
        trash: true,
      },
      defaultMode: "draw_polygon",
    });

    drawRef.current = draw;
    map.addControl(draw);

    // When draw changes (create/update/delete), notify parent
    const emitDrawState = () => {
      try {
        const data = draw.getAll();
        if (typeof onDrawChange === "function") onDrawChange(data);
      } catch (e) {
        if (typeof onDrawChange === "function") onDrawChange({ type: "FeatureCollection", features: [] });
      }
    };

    map.on("draw.create", emitDrawState);
    map.on("draw.update", emitDrawState);
    map.on("draw.delete", emitDrawState);

    // remove on unmount
    return () => {
      if (map) {
        map.off("draw.create", emitDrawState);
        map.off("draw.update", emitDrawState);
        map.off("draw.delete", emitDrawState);
        map.removeControl(draw);
        map.remove();
      }
      drawRef.current = null;
      mapInstance.current = null;
    };
  }, [center, zoom, apiKey, onDrawChange]);

  // helper to programmatically get drawn GeoJSON (optional)
  // parent can access by keeping a ref to this component via forwardRef if needed.
  return <div ref={mapRef} style={{ width: "100%", height: "100%" }} />;
}
